// 请求去重（in-flight map）+ 取消（AbortController 语义的确定性实现）
function createClient() {
  const inflight = new Map();   // key -> handle
  const queue = [];             // 待结算的在飞请求（逻辑队列，非墙钟）
  let sent = 0;
  let seq = 0;
  return {
    get sent() { return sent; },
    get inflight() { return inflight.size; },
    request(key) {
      if (inflight.has(key)) return { deduped: true, handle: inflight.get(key) };
      sent += 1;
      const handle = { key, seq: seq++, cancelled: false, settled: false, result: null };
      inflight.set(key, handle);
      queue.push(handle);
      return { deduped: false, handle };
    },
    cancel(key) {
      const h = inflight.get(key);
      if (!h) return false;
      h.cancelled = true;
      inflight.delete(key);
      return true;
    },
    drain() {                       // 结算队首的在飞请求
      const h = queue.shift();
      if (!h) return null;
      h.settled = true;
      if (!h.cancelled) {
        h.result = 'data:' + h.key;
        if (inflight.get(h.key) === h) inflight.delete(h.key);
      }
      return h;
    },
  };
}

// A. 去重
